impl Solution {
    pub fn min_cutting_cost(n: i32, m: i32, k: i32) -> i64 {
        let n = n as i64;
        let m = m as i64;
        let k = k as i64;

        if n <= k && m <= k {
            return 0;
        }

        let mut cost = 0;

        if n > k {
            cost += (n - k) * k;
        }

        if m > k {
            cost += (m - k) * k;
        }

        cost
    }
}

